.modal-ok:hover{background:#d9b56b2c}
/* The satin underdress remains visible as each removable outer layer fades away. */
.outer-sleeves,.outer-skirt,.outer-bodice{transition:opacity .4s ease,transform .4s ease;transform-origin:center}
.princess.level-1 .outer-sleeves,.princess.level-2 .outer-sleeves,.princess.level-3 .outer-sleeves{opacity:0;transform:translateY(12px)}
.princess.level-2 .outer-skirt,.princess.level-3 .outer-skirt{opacity:0;transform:translateY(18px)}
.princess.level-3 .outer-bodice{opacity:0;transform:translateY(-8px)}
.wardrobe-note{display:block;color:#867a90;font-size:9px;line-height:1.4;margin-top:8px}
.gear-meter{margin:-7px 0 15px;padding:10px 12px;border:1px solid #f0dfc219;border-radius:11px;background:#ffffff04}
.gear-heading{display:flex;justify-content:space-between;align-items:center;color:#a89bb1;font-size:9px;font-weight:700;letter-spacing:.14em}
.gear-heading b{color:#e2c78e;letter-spacing:.06em}
.gear-pips{display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin-top:8px}
.gear-pips i{height:6px;border-radius:8px;background:linear-gradient(90deg,#ba8d60,#f0d496);box-shadow:0 0 8px #e6bf7744;transition:opacity .25s,background .25s}
.gear-pips i.spent{background:#ffffff12;box-shadow:none}
.outcome-card{width:min(440px,100%);max-height:min(92svh,700px);overflow:auto;text-align:center;padding:24px 28px 26px;background:radial-gradient(ellipse at 50% 0,#56406066,transparent 58%),linear-gradient(150deg,#30263b,#211a30);border:1px solid #e6ce9e45;border-radius:20px;box-shadow:var(--shadow);animation:outcome-in .28s ease-out}
.outcome-art{height:185px;display:grid;place-items:center;margin:-3px 0 4px;border-radius:14px;background:radial-gradient(ellipse at 60% 75%,#c3996c20,transparent 65%),#17122255;overflow:hidden}
.outcome-art svg{display:block;width:100%;height:100%;max-height:185px}
.outcome-card h2{font:500 34px 'Playfair Display',Georgia,serif;color:#f0d49b;margin:8px 0 10px}
.outcome-card p{color:#c1b4c6;font-size:13px;line-height:1.6;margin:0 auto;max-width:350px}
.outcome-card .modal-ok{margin-top:20px}
@keyframes outcome-in{from{opacity:0;transform:translateY(8px) scale(.98)}to{opacity:1;transform:translateY(0) scale(1)}}
@media(max-width:760px){.gear-meter{margin:-5px 0 10px;padding:8px 10px}.outcome-card{padding:18px 20px 20px}.outcome-art{height:150px}.outcome-art svg{max-height:150px}}
